public class BooleanRuleSimplifierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final boolean[] BOTH = {true, false};

    static String checkOutTable() {
        StringBuilder table = new StringBuilder();
        for (boolean member : BOTH) {
            for (boolean fines : BOTH) {
                for (boolean override : BOTH) {
                    table.append(BooleanRuleSimplifier.canCheckOut(member, fines, override) ? 'T' : 'F');
                }
            }
        }
        return table.toString();
    }

    static String exactlyOneTable() {
        StringBuilder table = new StringBuilder();
        for (boolean a : BOTH) {
            for (boolean b : BOTH) {
                for (boolean c : BOTH) {
                    table.append(BooleanRuleSimplifier.exactlyOne(a, b, c) ? 'T' : 'F');
                }
            }
        }
        return table.toString();
    }

    public static void main(String[] args) {
        check("canCheckOut(member, no fines, no override)", true,
                BooleanRuleSimplifier.canCheckOut(true, false, false));
        check("canCheckOut(member, fines, no override)", false,
                BooleanRuleSimplifier.canCheckOut(true, true, false));
        check("canCheckOut(not a member, fines, override)", true,
                BooleanRuleSimplifier.canCheckOut(false, true, true));
        check("canCheckOut full truth table (TTT..FFF)", "TFTTTFTF", checkOutTable());
        check("exactlyOne(true, false, false)", true,
                BooleanRuleSimplifier.exactlyOne(true, false, false));
        check("exactlyOne(true, true, false)", false,
                BooleanRuleSimplifier.exactlyOne(true, true, false));
        check("exactlyOne(false, false, true)", true,
                BooleanRuleSimplifier.exactlyOne(false, false, true));
        check("exactlyOne full truth table (TTT..FFF)", "FFFTFTTF", exactlyOneTable());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

