public class BooleanRuleSimplifier {

    public static boolean canCheckOut(boolean isMember, boolean hasUnpaidFines, boolean staffOverride) {
        return staffOverride || (isMember && !hasUnpaidFines);
    }

    public static boolean exactlyOne(boolean a, boolean b, boolean c) {
        int trueCount = 0;
        if (a) {
            trueCount++;
        }
        if (b) {
            trueCount++;
        }
        if (c) {
            trueCount++;
        }
        return trueCount == 1;
    }
}
